          "support": "The THz probe reached the sample at normal incidence in reflection geometry (Fig.1(b))."
        }
      ]
    },
    {
      "condition_id": "bulk_single_crystal",
      "statement": "Millimeter-thick bulk single crystals of NiPS3 with Néel temperature 155 K.",
      "anchors": [
        {
          "line_start": 54,
          "line_end": 54,
          "support": "Millimeter-thick bulk single crystals of NiPS3 with a Néel temperature (TN) of 155 K were grown by the chemical vapor transport method."
        }
      ]
    }
