  "controls": [
    {
      "name": "pump_photon_energy",
      "definition": "Energy of the optical pump photons used to excite the sample.",
      "unit": "eV",
      "minimum": 1.476,
      "maximum": 1.61,
      "anchors": [
        {
          "line_start": 61,
          "line_end": 61,
          "support": "Optical excitation at three selected frequencies was used to drive NiPS3 out of equilibrium: (1) resonant pumping of the exciton at 1.476 eV, (2) resonant pumping of the magnon sideband of the exciton at 1.494 eV, and (3) off-resonant pumping at 1.61 eV which is slightly above the absorption onset at 7 K."
        }
      ]
    },
    {
      "name": "temperature",
      "definition": "Sample temperature during the pump-probe measurement.",
      "unit": "K",
      "minimum": 7,
      "maximum": 300,
      "anchors": [
        {
          "line_start": 72,
          "line_end": 72,
          "support": "Figure 2(c) shows a set of pump-probe overlap scans at various temperatures across TN = 155 K ... With increasing temperature, the exciton peak red-shifts and broadens considerably at 70 K, before nearly disappearing at 130 K. ... a positive ΔE/E is seen at room temperature with 1.476 eV pumping."
        }
      ]
    },
    {
      "name": "pump_fluence",
      "definition": "Incident pump fluence used in the fluence dependence measurement of spectral weight.",
      "unit": "arbitrary units",
